from collections import defaultdict
class Solution:
    def delayedCountOfEqualElements(self, nums: List[int], k: int) -> List[int]:
        n = len(nums)
        ans = [0] * n
        cnt = defaultdict(int)
        for i in range(n - 1, -1, -1):
            j = i + k + 1
            if j < n:
                cnt[nums[j]] += 1
            ans[i] = cnt[nums[i]]
        return ans

