from collections import defaultdict
import bisect
class Solution:
    def delayedCountOfEqualElements(self, nums: List[int], k: int) -> List[int]:
        pos = defaultdict(list)
        for i, x in enumerate(nums):
            pos[x].append(i)
        ans = []
        for i, x in enumerate(nums):
            lst = pos[x]
            p = bisect.bisect_right(lst, i + k)
            ans.append(len(lst) - p)
        return ans

