import java.util.*;
class Solution {
    public int[] delayedCountOfEqualElements(int[] nums, int k) {
        int n = nums.length;
        Map<Integer, List<Integer>> pos = new HashMap<>();
        for (int i = 0; i < n; i++)
            pos.computeIfAbsent(nums[i], x -> new ArrayList<>()).add(i);
        int[] ans = new int[n];
        for (int i = 0; i < n; i++) {
            List<Integer> lst = pos.get(nums[i]);
            int lo = 0, hi = lst.size();
            while (lo < hi) {
                int mid = (lo + hi) >>> 1;
                if (lst.get(mid) <= i + k) lo = mid + 1; else hi = mid;
            }
            ans[i] = lst.size() - lo;
        }
        return ans;
    }
}

