var delayedCountOfEqualElements = function(nums, k) {
    const pos = new Map();
    nums.forEach((x, i) => {
        if (!pos.has(x)) pos.set(x, []);
        pos.get(x).push(i);
    });
    return nums.map((x, i) => {
        const lst = pos.get(x);
        let lo = 0, hi = lst.length;
        while (lo < hi) {
            const mid = (lo + hi) >> 1;
            if (lst[mid] <= i + k) lo = mid + 1; else hi = mid;
        }
        return lst.length - lo;
    });
};
